package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Single source of truth for the owner "E.164 telephone" rule. Both
 * {@link NormalizeOwnerTelephone} (which stores the E.164 value) and
 * {@link OwnerIdentity} (which uses it as the telephone part of the identity key) go through
 * here, so the two can never drift apart.
 *
 * <p>The rule: strip spaces, dashes and brackets; keep a leading {@code '+'} and country
 * code when present, otherwise assume country code {@code '+61'} and drop a single leading
 * {@code '0'} from the national digits; require 8 to 15 digits after the {@code '+'}. So
 * {@code "0412 345 678"} becomes {@code "+61412345678"}.
 *
 * <p>For a recognised country code the national-number length is also fixed: {@code '+61'}
 * requires exactly 9 national digits and {@code '+1'} exactly 10. A number whose country
 * code is known but whose national length is wrong is rejected (returns {@code null}).
 */
public final class OwnerTelephones {

    /**
     * Recognised country codes mapped to the exact number of national digits they require.
     * Ordered longest-prefix first so a leading {@code "61"} matches country {@code "61"}
     * before the shorter {@code "1"}.
     */
    private static final Map<String, Integer> NATIONAL_DIGITS = new LinkedHashMap<>();

    static {
        NATIONAL_DIGITS.put("61", 9);
        NATIONAL_DIGITS.put("1", 10);
    }

    private OwnerTelephones() {
    }

    /**
     * Converts {@code telephone} to its E.164 form, or returns {@code null} when it cannot
     * form a valid E.164 number (null input, non-digit content, fewer than 8 / more than
     * 15 digits after the {@code '+'}, or a recognised country code with the wrong
     * national-number length).
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        // Strip spaces, dashes and brackets; any other non-digit is left in place so it
        // fails the digits check below.
        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            // Explicit country code: keep it, drop the leading '+'.
            digits = cleaned.substring(1);
        } else {
            // No country code: assume '+61' and drop a single leading '0' from the national
            // digits.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("\\d{8,15}")) {
            return null;
        }
        // For a recognised country code, the national-number length is fixed.
        for (Map.Entry<String, Integer> country : NATIONAL_DIGITS.entrySet()) {
            String code = country.getKey();
            if (digits.startsWith(code)) {
                int nationalLength = digits.length() - code.length();
                return nationalLength == country.getValue() ? "+" + digits : null;
            }
        }
        return "+" + digits;
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "bulkSignupWarning",
        expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
    @Mapping(target = "possibleDuplicate",
        expression = "java(Boolean.TRUE.equals(owner.getPossibleDuplicate()))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
    @Mapping(target = "identityKey",
        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner))")
    OwnerDto toOwnerDto(Owner owner);

    /**
     * Derives the owner's age band from the {@code birthDate} measured against the
     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to
     * 64 inclusive and {@code SENIOR} at 65 or over. Null when no birth date is present.
     */
    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
        java.time.LocalDate birthDate = owner.getBirthDate();
        if (birthDate == null) {
            return null;
        }
        java.time.LocalDate reference = owner.getRegistrationDate() != null
            ? owner.getRegistrationDate() : java.time.LocalDate.now();
        int years = java.time.Period.between(birthDate, reference).getYears();
        if (years < 18) {
            return OwnerDto.AgeBandEnum.MINOR;
        }
        if (years < 65) {
            return OwnerDto.AgeBandEnum.ADULT;
        }
        return OwnerDto.AgeBandEnum.SENIOR;
    }

    /**
     * Derives the owner's preferred contact channel: {@code EMAIL} when an email
     * address is present (non-null and not blank), otherwise {@code PHONE}.
     */
    default String contactPreference(Owner owner) {
        String email = owner.getEmail();
        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
    }

    /**
     * Derives the owner's locality (region) from the owner's {@code customerCode}
     * identity ({@code <REGION>-<HASH8>}): the locality is the {@code REGION} segment
     * of that identity. When the customer code has not been assigned yet, it falls
     * back to deriving the region directly (see
     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion}).
     */
    default String locality(Owner owner) {
        String region = org.springframework.samples.petclinic.rest.function.owner.OwnerRegion
            .regionFromCustomerCode(owner.getCustomerCode());
        return region != null ? region
            : org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(owner);
    }

    /**
     * Derives the owner's membership number, formatted {@code <customerCode>-M<YY>}
     * where {@code YY} is the last two digits of the registration-date year
     * (e.g. {@code NSW-1A2B3C4D-M26}). Null when either source field is absent.
     */
    default String membershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
    }

    /**
     * Computes a single Luhn check digit (0-9) over the digits contained in the
     * owner's {@code customerCode}. Null when the customer code is absent.
     */
    default Integer checkDigit(Owner owner) {
        String customerCode = owner.getCustomerCode();
        if (customerCode == null) {
            return null;
        }
        int sum = 0;
        boolean dbl = true;
        for (int i = customerCode.length() - 1; i >= 0; i--) {
            char c = customerCode.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

